// pg reads process.env (PGHOST, PGUSER and so on) and process.platform as it does in Node.
const { Pool } = require('pg');

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

kcds.core.Events.on('playerConnect', async (player) => {
  await pool.query('INSERT INTO joins (steam_id) VALUES ($1)', [player.steamId]);
});
